function renderChecklist(key) {
  const c = CHECKLISTS[key];
  const lines = c.checks.map(function (chk, i) {
    return '   ' + (i + 1) + '. [' + chk.sev + '] (' + chk.id + ') ' + chk.text +
           '\n      Authority: ' + chk.ref;
  }).join('\n');
  return '## ' + key + ' — ' + c.label + '\n' +
         'Governing standard: ' + c.primary + '\n' + lines;
